<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Farming Game</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        let player = { x: 0, y: 0 };
        let tiles = {};
        let inventory = { seeds: 5, crops: 0 };
        let day = 0;

        const tileSize = 50;
        const tileWidth = canvas.width / tileSize;
        const tileHeight = canvas.height / tileSize;

        function drawPlayer() {
            ctx.fillStyle = 'green';
            ctx.fillRect(player.x * tileSize, player.y * tileSize, tileSize, tileSize);
        }

        function drawTile(x, y, crop, stage) {
            ctx.fillStyle = crop === 'seed' ? 'red' : 'green';
            ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);
            ctx.fillStyle = 'black';
            ctx.fillText(`Stage: ${stage}`, x * tileSize + 10, y * tileSize + 10);
        }

        function drawInventory() {
            ctx.fillStyle = 'blue';
            ctx.fillRect(0, canvas.height - 50, 100, 50);
            ctx.fillStyle = 'white';
            ctx.fillText(`Seeds: ${inventory.seeds}`, 10, canvas.height - 30);
            ctx.fillText(`Crops: ${inventory.crops}`, 10, canvas.height - 10);
        }

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            drawPlayer();
            for (let key in tiles) {
                const tile = tiles[key];
                drawTile(key.split(',')[0], key.split(',')[1], tile.crop, tile.stage);
            }
            drawInventory();
            document.title = `Day: ${day}`;
        }

        function movePlayer(event) {
            const dx = event.key === 'ArrowLeft' ? -1 : event.key === 'ArrowRight' ? 1 : 0;
            const dy = event.key === 'ArrowUp' ? -1 : event.key === 'ArrowDown' ? 1 : 0;
            player.x += dx;
            player.y += dy;
            draw();
        }

        function plantSeed() {
            const key = `${player.x},${player.y}`;
            if (!tiles[key]) {
                tiles[key] = { crop: 'seed', stage: 0 };
                inventory.seeds--;
                draw();
            }
        }

        function advanceTime() {
            day++;
            draw();
        }

        function harvestCrop() {
            const key = `${player.x},${player.y}`;
            if (tiles[key] && tiles[key].crop === 'seed') {
                tiles[key].crop = 'crop';
                inventory.crops++;
                draw();
            }
        }

        function saveGame() {
            localStorage.setItem('game', JSON.stringify({ player, tiles, inventory, day }));
        }

        function loadGame() {
            const savedGame = localStorage.getItem('game');
            if (savedGame) {
                const game = JSON.parse(savedGame);
                player = game.player;
                tiles = game.tiles;
                inventory = game.inventory;
                day = game.day;
                draw();
            }
        }

        document.addEventListener('keydown', movePlayer);
        document.addEventListener('keydown', (event) => {
            if (event.key === 'p') {
                plantSeed();
            } else if (event.key === 't') {
                advanceTime();
            } else if (event.key === 'h') {
                harvestCrop();
            } else if (event.key === 's') {
                saveGame();
            }
        });

        loadGame();
    </script>
</body>
</html>
